<template>
  <WorkbenchShell role="cs" active="pool" title="抢单池" subtitle="监控待抢订单，超时订单优先处理并可人工指派">
    <template #actions><view class="summary-pill"><text>{{ sortedPool.length }}</text><text>待抢订单</text></view></template>
    <view class="toolbar"><view><view class="live-dot"/><text>订单池实时更新</text></view><text>超过 30 分钟将标记为超时并置顶</text><button @click="load">立即刷新</button></view>
    <view v-if="error" class="error-box"><text>{{ error }}</text><button @click="load">重试</button></view>
    <view v-if="sortedPool.length" class="pool-grid"><view v-for="order in sortedPool" :key="oid(order)" class="order-card" :class="{timeout:isTimeout(order)}">
      <view class="order-head"><view><text class="order-title">{{ order.productTitle||productName(order) }}</text><text class="order-no">{{ order.orderNo }}</text></view><text v-if="isTimeout(order)" class="timeout-tag">需要优先处理</text></view>
      <view class="detail-grid"><view><text>游戏与区服</text><text>{{ gameText(order.game) }} · {{ order.region||'待确认' }}</text></view><view><text>服务类型</text><text>{{ serviceTypeText(order.serviceType) }}</text></view><view><text>入池时长</text><text>{{ poolDuration(order) }}</text></view><view><text>当前接单人</text><text>{{ order.workerName||order.workerId||'等待接单' }}</text></view></view>
      <view class="order-footer"><text class="order-amount">¥{{ fenToYuan(order.amountFen) }}</text><button class="primary-btn" @click="openAssign(order)">指派人员</button></view>
    </view></view>
    <view v-if="!error&&sortedPool.length===0" class="empty"><view class="empty-icon"><view class="empty-shape"/></view><text>当前没有待抢订单</text><text>新订单进入后会自动显示在这里</text></view>
    <view v-if="assignTarget" class="mask" @click="closeAssign"><view class="dialog" @click.stop><view class="dialog-head"><view><text>指派服务人员</text><text>{{ assignTarget.orderNo }} · {{ assignTarget.productTitle||productName(assignTarget) }}</text></view><button @click="closeAssign">关闭</button></view><text class="field-label">选择接单人员</text><picker mode="selector" :range="workerLabels" @change="onWorkerChange"><view class="picker-value">{{ selectedWorkerLabel||'请选择接单人员' }} ▾</view></picker><view class="dialog-btns"><button class="secondary-btn" @click="closeAssign">取消</button><button class="primary-btn" :disabled="busy||!selectedWorkerId" @click="doAssign">{{ busy?'指派中…':'确认指派' }}</button></view></view></view>
  </WorkbenchShell>
</template>

<script setup>
import { computed,ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { api } from '../../api.js';import { guard,oid,fenToYuan } from '../../common.js';import { gameText,serviceTypeText } from '../../utils/display.js';import WorkbenchShell from '../../components/WorkbenchShell.vue';
const POOL_TIMEOUT_MS=30*60*1000;const pool=ref([]);const workers=ref([]);const error=ref('');const busy=ref(false);const assignTarget=ref(null);const selectedWorkerId=ref('');const selectedWorkerLabel=ref('');const workerLabels=computed(()=>workers.value.map((worker)=>`${worker.nickname||'未命名'} · ${worker.phone||'无手机号'} · 进行中 ${worker.activeCount??0}`));
const sortedPool=computed(()=>[...pool.value].sort((a,b)=>{const ta=isTimeout(a)?0:1;const tb=isTimeout(b)?0:1;return ta!==tb?ta-tb:(b.pooledAt||0)-(a.pooledAt||0);}));
function isTimeout(order){if(order&&order.timeout)return true;const time=Number(order&&(order.pooledAt||order.createdAt||0));return time>0&&Date.now()-time>POOL_TIMEOUT_MS;}function poolDuration(order){const time=Number(order&&(order.pooledAt||order.createdAt||0));if(!time)return'待确认';const minutes=Math.max(0,Math.floor((Date.now()-time)/60000));return minutes<1?'刚刚进入':minutes<60?`${minutes} 分钟`:`${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟`;}function productName(order){const snapshot=order.productSnapshot||{};return snapshot.title||snapshot.name||'服务订单';}
async function load(){error.value='';try{const[list,staff]=await Promise.all([api.listPool(),api.listWorkers()]);pool.value=Array.isArray(list)?list:[];workers.value=Array.isArray(staff)?staff:[];}catch(e){error.value=e.message||'订单池加载失败';}}
function openAssign(order){assignTarget.value=order;selectedWorkerId.value='';selectedWorkerLabel.value='';}function closeAssign(){assignTarget.value=null;}function onWorkerChange(event){const index=Number(event.detail.value);const worker=workers.value[index];selectedWorkerId.value=worker?(worker._id||worker.id):'';selectedWorkerLabel.value=workerLabels.value[index]||'';}
async function doAssign(){if(!assignTarget.value||!selectedWorkerId.value)return;busy.value=true;try{await api.assignOrder(oid(assignTarget.value),selectedWorkerId.value);uni.showToast({title:'指派成功',icon:'success'});closeAssign();load();}catch(e){uni.showToast({title:e.message||'指派失败',icon:'none'});}finally{busy.value=false;}}
onLoad(()=>{if(!guard(['CS']))return;load();});
</script>

<style lang="scss" scoped>
.summary-pill{padding:8px 12px;display:flex;align-items:baseline;gap:6px;color:var(--es-primary);background:#eef0ff;border-radius:9px}.summary-pill text:first-child{font-size:18px;font-weight:700}.summary-pill text:last-child{font-size:11px}.toolbar{margin-bottom:18px;padding:13px 16px;display:flex;align-items:center;gap:12px;color:var(--es-text-dim);font-size:12px;background:#fff;border:1px solid var(--es-border-soft);border-radius:10px}.toolbar>view{display:flex;align-items:center;gap:8px;color:#027a48;font-weight:600}.live-dot{width:8px;height:8px;background:var(--es-success);border-radius:50%;box-shadow:0 0 0 4px #ecfdf3}.toolbar>text{flex:1}.toolbar button,.error-box button{width:auto;height:32px;margin:0;padding:0 12px;color:var(--es-primary);font-size:12px;line-height:32px;background:#fff;border:1px solid #c7d7fe;border-radius:8px}.pool-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.order-card{padding:20px;background:#fff;border:1px solid var(--es-border-soft);border-radius:14px;box-shadow:var(--es-glow)}.order-card.timeout{border-color:#fedf89;box-shadow:inset 4px 0 #f79009}.order-head,.order-footer{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.order-title,.order-no{display:block}.order-title{font-size:16px;font-weight:700}.order-no{margin-top:5px;color:var(--es-text-dim);font-size:11px}.timeout-tag{padding:5px 9px;color:#b54708;font-size:11px;font-weight:600;background:#fffaeb;border-radius:999px}.detail-grid{margin-top:18px;padding:15px;display:grid;grid-template-columns:1fr 1fr;gap:15px;background:#f8f9fc;border-radius:10px}.detail-grid text{display:block}.detail-grid text:first-child{color:var(--es-text-dim);font-size:11px}.detail-grid text:last-child{margin-top:4px;color:var(--es-text);font-size:13px;font-weight:500}.order-footer{margin-top:18px;align-items:center}.order-amount{font-size:22px;font-weight:700}.primary-btn,.secondary-btn{width:auto;height:38px;margin:0;padding:0 18px;font-size:13px;line-height:38px;border-radius:9px}.primary-btn{color:#fff;font-weight:600;background:var(--es-primary)}.primary-btn[disabled]{opacity:.55}.secondary-btn{color:var(--es-text-dim);background:#fff;border:1px solid var(--es-border)}.empty{min-height:340px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--es-text-dim);background:#fff;border:1px solid var(--es-border-soft);border-radius:14px}.empty>text:nth-child(2){margin-top:14px;color:var(--es-text);font-size:15px;font-weight:600}.empty>text:last-child{margin-top:6px;font-size:12px}.empty-icon{width:64px;height:64px;display:flex;align-items:center;justify-content:center;background:#eef0ff;border-radius:20px}.empty-icon i{width:24px;height:24px;border:3px solid var(--es-primary);border-radius:7px}.error-box{margin-bottom:14px;padding:12px 14px;display:flex;justify-content:space-between;color:#b42318;font-size:12px;background:#fef3f2;border:1px solid #fecdca;border-radius:9px}.mask{position:fixed;inset:0;z-index:80;padding:20px;display:flex;align-items:center;justify-content:center;background:rgba(16,24,40,.58)}.dialog{width:100%;max-width:480px;padding:24px;background:#fff;border-radius:16px;box-shadow:0 24px 64px rgba(16,24,40,.24)}.dialog-head{display:flex;justify-content:space-between}.dialog-head text{display:block}.dialog-head text:first-child{font-size:18px;font-weight:700}.dialog-head text:last-child{margin-top:5px;color:var(--es-text-dim);font-size:12px}.dialog-head button{width:auto;height:30px;margin:0;padding:0 8px;color:var(--es-text-dim);font-size:11px;line-height:30px;background:transparent}.field-label{display:block;margin:24px 0 8px;font-size:13px;font-weight:600}.picker-value{height:42px;padding:0 13px;display:flex;align-items:center;font-size:13px;background:#fff!important;border:1px solid var(--es-border);border-radius:9px}.dialog-btns{margin-top:24px;display:flex;justify-content:flex-end;gap:10px}
@media(max-width:900px){.pool-grid{grid-template-columns:1fr}}@media(max-width:767px){.toolbar{align-items:flex-start;flex-wrap:wrap}.toolbar>text{min-width:100%;order:3}.pool-grid{gap:12px}.order-card{padding:16px}.detail-grid{grid-template-columns:1fr 1fr;padding:13px}.mask{align-items:flex-end}.dialog{border-radius:18px 18px 0 0}}
.empty-shape{width:24px;height:24px;border:3px solid var(--es-primary);border-radius:7px}
</style>
